/* ============ Decision spine v2 (pilot: mdd; claude/SPINE_SPEC.md). Sculpted only: every surface is a theme token (wells use
   --inner, raised parts use --e2, colors use the paired tints), so flat mode and study mode follow automatically. No raw colors:
   build.py refuses this file if it holds a hex value. ============ */
.brief.sp .sp-step{display:grid;grid-template-columns:repeat(9,minmax(0,1fr));gap:6px;margin:6px 0 20px}
.brief.sp .sp-step a{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;min-height:44px;padding:6px 2px;border-radius:12px;background:var(--raised);box-shadow:var(--e2);color:var(--confirm);text-decoration:none}
.brief.sp .sp-step a b{font:800 13px/1 var(--sans)}
.brief.sp .sp-step a span{font:600 11px/1.15 var(--sans);text-align:center;color:var(--ink-2)}
.brief.sp .sp-step a.sp-prac{color:var(--accent)}
.brief.sp .sp-step a.sp-prac span{color:var(--accent)}
@media (max-width:640px){.brief.sp .sp-step{grid-template-columns:repeat(8,minmax(0,1fr)) auto;gap:4px}.brief.sp .sp-step a span{display:none}.brief.sp .sp-step a.sp-prac{padding:6px 8px}.brief.sp .sp-step a.sp-prac span{display:block;font-size:10.5px}}
.brief.sp h5.sp-h{display:flex;align-items:center;gap:10px;border-left:0;padding-left:0;margin:32px 0 12px}
.brief.sp .sp-n{display:inline-grid;place-items:center;min-width:28px;height:28px;border-radius:9px;background:var(--confirm);color:var(--raised);font:800 14px/1 var(--sans)}
.brief.sp .sp-prob{font-size:15.5px;line-height:1.5;margin:0 0 8px;color:var(--ink)}
.brief.sp .sp-qual{display:flex;flex-wrap:wrap;gap:7px;margin:0 0 14px}
.brief.sp .sp-qual span{font:600 12.5px/1.2 var(--sans);padding:5px 11px;border-radius:99px;box-shadow:inset 0 0 0 1px var(--hair);color:var(--ink-2)}
/* rows are recessed wells, the same surface as the criteria tile */
.brief.sp .sp-rows{display:grid;gap:10px;align-items:start}
@media (min-width:900px){.brief.sp .sp-rows.sp-by{grid-template-columns:repeat(3,minmax(0,1fr))}}
.brief.sp .sp-row{padding:13px 16px;border-radius:var(--r-sub);background:var(--recess);box-shadow:var(--inner);min-width:0}
.brief.sp .sp-src{display:block;font:800 10.5px/1.25 var(--sans);letter-spacing:.08em;text-transform:uppercase;color:var(--criteria);margin:0 0 4px}
.brief.sp .sp-f{font-size:15px;line-height:1.42;color:var(--ink)}
.brief.sp .sp-note{display:block;margin:4px 0 0;font-size:14px;line-height:1.45;color:var(--ink-2)}
.brief.sp .sp-chips{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px;align-items:center}
.brief.sp .sp-chip{display:inline-block;font:650 12.5px/1.35 var(--sans);padding:3px 9px;border-radius:8px}
.brief.sp .sp-chip.role{background:var(--accent-bg);color:var(--accent)}
.brief.sp .sp-chip.pop{background:var(--principle-bg);color:var(--principle)}
.brief.sp .sp-chip.warn{background:var(--caution-bg);color:var(--caution)}
.brief.sp .sp-chip.mnm{background:var(--caution-bg);color:var(--caution);font-size:11.5px;padding:2px 7px;font-weight:800;letter-spacing:.02em}
.brief.sp .sp-commit{margin:10px 0 0;padding-top:9px;border-top:1px dashed var(--hair);font-size:14.5px;line-height:1.45;color:var(--ink)}
.brief.sp .sp-commit > b{color:var(--accent)}
.brief.sp .sp-pause{margin:12px 0 0;padding:12px 15px;border-radius:0 var(--r-sub) var(--r-sub) 0;border-left:3px solid var(--caution);background:var(--caution-bg);font-size:14.5px;line-height:1.5}
.brief.sp .sp-pause > b:first-child{color:var(--caution)}
/* tier labels are flat small-caps tags, never raised inside a tile (Jonathan 2026-10-07) */
.brief.sp .sp-tier{display:grid;grid-template-columns:64px minmax(0,1fr);gap:12px;align-items:start}
.brief.sp .sp-tp{font:800 11.5px/1.3 var(--sans);letter-spacing:.07em;text-transform:uppercase;color:var(--criteria);padding-top:3px}
.brief.sp .sp-dx table{width:100%}
.brief.sp .sp-dx td{vertical-align:top}
.brief.sp .sp-dx td:first-child{font-weight:650;color:var(--ink)}
/* phone table cards: the site-wide rule (s116) keeps every value on one left edge */
/* inline explanations: a hover or click card on desktop, a tap-open block on phones */
.brief.sp .sp-pop{all:unset;cursor:pointer;color:var(--accent);font-weight:800;border-bottom:1.5px dotted currentColor}
.brief.sp .sp-pop.sp-why{display:flex;width:max-content;max-width:100%;box-sizing:border-box;align-items:center;gap:6px;min-height:32px;margin-top:6px;padding:2px 10px;border:0;border-radius:9px;background:var(--raised);box-shadow:var(--e2);font:750 13px/1.2 var(--sans);color:var(--principle)}
.brief.sp .sp-pop.sp-why::before{content:"?";display:inline-grid;place-items:center;width:17px;height:17px;border-radius:50%;background:var(--principle-bg);font:800 11px/1 var(--sans)}
.brief.sp .sp-pop:focus-visible,.brief.sp .sp-drw:focus-visible,.brief.sp details summary:focus-visible{outline:2px solid var(--accent);outline-offset:2px;border-radius:4px}
.brief.sp .sp-pop-b{display:block;margin:8px 0 2px;padding:11px 14px;border-radius:var(--r-sub);background:var(--recess);box-shadow:var(--inner);font-size:14px;font-weight:400;line-height:1.5;color:var(--ink-2)}
.brief.sp .sp-pop-b[hidden]{display:none}
.sp-pop-b .sp-ct,.sp-card .sp-ct{display:block;margin:0 0 5px;font:800 10.5px/1.2 var(--sans);letter-spacing:.08em;text-transform:uppercase;color:var(--principle)}
.sp-pop-b .sp-why-l,.sp-card .sp-why-l{display:block;margin-top:7px;padding-top:7px;border-top:1px dashed var(--hair)}
.sp-pop-b .sp-why-l b,.sp-card .sp-why-l b{color:var(--accent)}
.sp-pop-b ol,.sp-card ol{margin:2px 0 0;padding-left:20px}
.sp-card{position:absolute;z-index:60;max-width:380px;padding:14px 16px;border-radius:var(--r-sub);background:var(--raised);box-shadow:var(--e2);color:var(--ink-2);font:400 14px/1.52 var(--sans)}
/* drawers: the reasoning moves into another brief */
.brief.sp .sp-drw,.sp-drawer .sp-drw{all:unset;cursor:pointer;display:inline-flex;align-items:center;gap:5px;min-height:32px;padding:3px 11px;border-radius:9px;background:var(--raised);box-shadow:var(--e2);color:var(--principle);font:750 13px/1.25 var(--sans)}
.brief.sp .sp-drw::after,.sp-drawer .sp-drw::after{content:"\203A";font-weight:800}
.sp-scrim{position:fixed;inset:0;z-index:70;background:var(--dk);opacity:.55}
.sp-drawer{position:fixed;z-index:71;top:24px;right:24px;bottom:24px;width:min(520px,90vw);overflow:auto;overscroll-behavior:contain;background:var(--canvas-a);box-shadow:var(--e1);border-radius:var(--r-card);padding:16px 16px 20px}
.sp-drawer .brief{zoom:.9}
@media (max-width:640px){.sp-drawer{top:auto;left:0;right:0;bottom:0;width:auto;max-height:86vh;border-radius:var(--r-card) var(--r-card) 0 0;padding:12px 8px calc(20px + env(safe-area-inset-bottom,0px))}.sp-drawer .brief{zoom:1}}
.sp-drawer .sp-dbar{position:sticky;top:-16px;z-index:2;display:flex;align-items:center;justify-content:space-between;gap:10px;margin:-16px -16px 10px;padding:12px 16px;background:var(--canvas-a)}
.sp-drawer .sp-dmeta{font:750 12px/1.3 var(--sans);letter-spacing:.06em;text-transform:uppercase;color:var(--principle)}
.sp-drawer .sp-dclose{all:unset;cursor:pointer;min-width:44px;min-height:44px;display:grid;place-items:center;border-radius:10px;background:var(--raised);box-shadow:var(--e2);font:750 14px/1 var(--sans);color:var(--ink);padding:0 12px}
.sp-drawer .brief{margin:0}
.sp-drawer .sp-dpractice{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:18px 0 0;padding:14px 16px;border-radius:var(--r-sub);background:var(--recess);box-shadow:var(--inner);font-size:14.5px;color:var(--ink-2)}
.sp-drawer .sp-dopen{display:inline-flex;align-items:center;min-height:44px;padding:0 16px;border-radius:10px;background:var(--accent);color:var(--raised);font:750 14px/1 var(--sans);text-decoration:none;white-space:nowrap}
/* timeline strip */
.brief.sp .sp-tl{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));margin:2px 0 12px;font-size:13px;line-height:1.35;color:var(--ink-2)}
.brief.sp .sp-tl div{border-top:4px solid var(--confirm);padding:7px 6px 0;min-width:0}
.brief.sp .sp-tl div:first-child{border-color:var(--recess-2)}
.brief.sp .sp-tl b{display:block;font:800 12px/1.2 var(--sans);color:var(--ink)}
/* PHQ-9 bands: the score picks the branch */
.brief.sp .sp-phq{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px;margin:0 0 10px}
.brief.sp .sp-phq > div{padding:10px 10px 11px;border-radius:12px;background:var(--recess);box-shadow:var(--inner);min-width:0}
.brief.sp .sp-phq b{display:block;font:800 14px/1.15 var(--sans);color:var(--ink)}
.brief.sp .sp-phq i{display:block;font:750 11px/1.2 var(--sans);font-style:normal;letter-spacing:.05em;text-transform:uppercase;color:var(--criteria);margin:2px 0 5px}
.brief.sp .sp-phq span{display:block;font-size:13px;line-height:1.38;color:var(--ink-2)}
.brief.sp .sp-phq > div.hi{background:var(--caution-bg)}
@media (max-width:640px){.brief.sp .sp-phq{grid-template-columns:1fr}.brief.sp .sp-phq > div{display:grid;grid-template-columns:74px minmax(0,1fr);column-gap:10px}.brief.sp .sp-phq b{grid-row:1 / 3;padding-top:1px}.brief.sp .sp-phq i,.brief.sp .sp-phq span{grid-column:2}.brief.sp .sp-phq i{margin:1px 0 3px}}
/* Frame: what the disease does, by system (collapsed; supports, never diagnoses) */
.brief.sp details.sp-sys{margin:16px 0 4px;border-radius:var(--r-sub);background:var(--raised);box-shadow:var(--e2);padding:4px 14px 6px}
.brief.sp details.sp-sys[open]{padding-bottom:14px}
.brief.sp details.sp-sys summary{list-style:none;cursor:pointer;display:flex;align-items:center;gap:10px;min-height:46px;font:750 15px/1.2 var(--sans);color:var(--principle)}
.brief.sp details.sp-sys summary::-webkit-details-marker{display:none}
.brief.sp details.sp-sys summary::before{content:"+";display:inline-grid;place-items:center;width:24px;height:24px;border-radius:7px;background:var(--principle-bg);font:800 15px/1 var(--sans)}
.brief.sp details.sp-sys[open] summary::before{content:"\2212"}
.brief.sp details.sp-sys summary small{margin-left:auto;font:600 12.5px/1.2 var(--sans);color:var(--muted)}
.brief.sp .sp-sysr{display:grid;gap:8px;margin-top:4px}
.brief.sp .sp-sysr > div{display:grid;grid-template-columns:120px minmax(0,1fr);gap:3px 14px;padding:12px 15px;border-radius:var(--r-sub);background:var(--recess);box-shadow:var(--inner)}
.brief.sp .sp-sysr .k{font:800 10.5px/1.3 var(--sans);letter-spacing:.08em;text-transform:uppercase;color:var(--principle);padding-top:3px}
.brief.sp .sp-sysr .f{font-size:15px;line-height:1.42;font-weight:650;color:var(--ink)}
.brief.sp .sp-sysr .w{grid-column:2;font-size:13.5px;line-height:1.42;color:var(--ink-2)}
.brief.sp .sp-sysr .w::before{content:"why ";font:800 10.5px/1 var(--sans);letter-spacing:.08em;text-transform:uppercase;color:var(--accent)}
@media (max-width:640px){.brief.sp .sp-sysr > div{grid-template-columns:1fr}.brief.sp .sp-sysr .w{grid-column:1}}
/* Confirm: the mnemonic block follows the criteria tile; its note sits close under it */
.brief.sp .sp-mnnote{margin:-12px 0 12px;font-size:13.5px}
/* Stratify: the scoring instrument itself, then its bands */
.brief.sp .sp-inst{margin:0 0 10px;padding:14px 16px;border-radius:var(--r-sub);background:var(--recess);box-shadow:var(--inner)}
.brief.sp .sp-ih{display:flex;flex-wrap:wrap;align-items:baseline;gap:4px 10px;margin:0 0 8px}
.brief.sp .sp-ih b{font:800 11.5px/1.2 var(--sans);letter-spacing:.08em;text-transform:uppercase;color:var(--criteria)}
.brief.sp .sp-ih span{font-size:14px;font-style:italic;color:var(--ink-2)}
.brief.sp .sp-items{margin:0;padding-left:22px;columns:2;column-gap:28px;font-size:14px;line-height:1.42;color:var(--ink)}
.brief.sp .sp-items li{break-inside:avoid;margin:0 0 5px;padding-left:2px}
.brief.sp .sp-items li::marker{font-weight:800;color:var(--criteria)}
.brief.sp .sp-items .sp-i9 .sp-chip{display:block;width:max-content;max-width:100%;margin-top:4px}
.brief.sp .sp-scale{display:flex;flex-wrap:wrap;align-items:center;gap:6px 14px;margin-top:10px;padding-top:9px;border-top:1px dashed var(--hair);font-size:13px;color:var(--ink-2)}
.brief.sp .sp-scale b{display:inline-grid;place-items:center;width:20px;height:20px;margin-right:5px;border-radius:6px;background:var(--criteria-bg);color:var(--criteria);font:800 12px/1 var(--sans)}
.brief.sp .sp-scale em{margin-left:auto;font-style:normal;font-weight:700;color:var(--ink)}
@media (max-width:640px){.brief.sp .sp-items{columns:1}.brief.sp .sp-scale{display:grid;grid-template-columns:1fr 1fr;gap:8px 10px}.brief.sp .sp-scale em{grid-column:1 / -1;margin-left:0}}
@media (min-width:641px){.brief.sp .sp-phq{grid-template-columns:repeat(5,minmax(0,1fr))}}
.brief.sp .sp-spec{margin-top:14px}
.brief.sp .sp-spec td:first-child{white-space:nowrap}
.brief.sp .sp-cw{display:block;margin-top:5px;font:700 12.5px/1.35 var(--sans);color:var(--caution)}
.brief.sp .sp-cn{display:block;margin-top:5px;font-size:13px;line-height:1.38;color:var(--ink-2)}
/* drawer emerges from the button that opened it (desktop) */
.sp-drawer.sp-g{transition:transform .46s cubic-bezier(.2,.9,.24,1.06),border-radius .46s ease,opacity .2s ease}
.sp-drawer.sp-g > *{transition:opacity .22s ease .14s}
.sp-drawer.sp-g0 > *{opacity:0}
.sp-scrim{transition:opacity .3s ease}
.sp-scrim.sp-g0{opacity:0 !important}
/* PHQ-9 as the form looks: items down, answer columns across */
.brief.sp .sp-form{display:grid;grid-template-columns:minmax(0,1fr) repeat(4,64px);font-size:14px;line-height:1.38}
.brief.sp .sp-form > div{display:contents}
.brief.sp .sp-form .hd span{padding:0 4px 8px;font:700 11px/1.2 var(--sans);color:var(--muted);text-align:center;border-bottom:1px solid var(--hair)}
.brief.sp .sp-form .hd span:first-child{text-align:left;padding-left:0;text-transform:uppercase;letter-spacing:.08em;font-weight:800;color:var(--criteria)}
.brief.sp .sp-form .hd span b{display:block;margin:0 auto 3px;width:20px;height:20px;line-height:20px;border-radius:6px;background:var(--criteria-bg);color:var(--criteria);font-size:12px}
.brief.sp .sp-form .it > span,.brief.sp .sp-form .it > i{padding:7px 4px;border-bottom:1px solid var(--hair)}
.brief.sp .sp-form .it > span{padding-left:0;color:var(--ink)}
.brief.sp .sp-form .it > span .n{display:inline-block;width:20px;color:var(--criteria);font-weight:800}
.brief.sp .sp-form .it > i{display:grid;place-items:center}
.brief.sp .sp-form .it > i::before{content:"";width:13px;height:13px;border-radius:50%;box-shadow:inset 0 0 0 1.5px var(--faint)}
.brief.sp .sp-form .it.i9 > span,.brief.sp .sp-form .it.i9 > i{background:var(--caution-bg)}
.brief.sp .sp-form .it.i9 .sp-chip{display:block;width:auto;max-width:100%;white-space:normal;margin:5px 0 0 20px;padding:0;background:none}
.brief.sp .sp-total{margin:10px 0 0;font:700 13.5px/1.3 var(--sans);color:var(--ink)}
@media (max-width:640px){.brief.sp .sp-form{grid-template-columns:minmax(0,1fr) repeat(4,30px)}.brief.sp .sp-form .hd span{font-size:0;padding-bottom:6px}.brief.sp .sp-form .hd span:first-child{font-size:11px}.brief.sp .sp-form .hd span b{font-size:12px;margin:0 auto}.brief.sp .sp-form .it > i::before{width:11px;height:11px}}
/* PHQ-9 total: a scale from 0 to 27; the diagnostic threshold (10 or more) is bracketed above it */
.brief.sp .sp-sbar{display:grid;grid-template-columns:repeat(28,minmax(0,1fr));column-gap:0;row-gap:6px;margin:14px 0 4px}
.brief.sp .sp-thr{grid-column:11 / 29;grid-row:1;display:flex;flex-wrap:wrap;align-items:baseline;gap:2px 8px;padding:0 0 7px 10px;border-left:3px solid var(--caution);border-top:3px solid var(--caution);border-radius:6px 6px 0 0}
.brief.sp .sp-thr b{font:800 15px/1.2 var(--sans);color:var(--caution);padding-top:6px}
.brief.sp .sp-thr span{font-size:13.5px;color:var(--ink-2)}
.brief.sp .sp-sbar .sg{grid-row:2;padding:9px 8px 10px;border-top:6px solid var(--recess-2);background:var(--recess);box-shadow:var(--inner);min-width:0}
.brief.sp .sp-sbar .s0{grid-column:1 / 6;border-radius:0 0 0 10px}
.brief.sp .sp-sbar .s1{grid-column:6 / 11;border-top-color:var(--criteria-bg)}
.brief.sp .sp-sbar .s2{grid-column:11 / 16;border-top-color:var(--criteria)}
.brief.sp .sp-sbar .s3{grid-column:16 / 21;border-top-color:var(--caution)}
.brief.sp .sp-sbar .s4{grid-column:21 / 29;border-top-color:var(--ink-2);border-radius:0 0 10px 0}
.brief.sp .sp-sbar .sg em{display:block;font:800 14px/1.15 var(--sans);font-style:normal;color:var(--ink)}
.brief.sp .sp-sbar .sg i{display:block;margin:2px 0 6px;font:750 10.5px/1.2 var(--sans);font-style:normal;letter-spacing:.06em;text-transform:uppercase;color:var(--criteria)}
.brief.sp .sp-sbar .sg span{display:block;font-size:13px;line-height:1.38;color:var(--ink-2)}
@media (max-width:640px){
  .brief.sp .sp-sbar{display:block}
  .brief.sp .sp-thr{margin:0 0 8px;padding:8px 10px;border:0;border-radius:10px;background:var(--caution-bg)}
  .brief.sp .sp-thr b{padding-top:0}
  .brief.sp .sp-sbar .sg{display:grid;grid-template-columns:74px minmax(0,1fr);column-gap:10px;margin:0 0 6px;border-top:0;border-left:6px solid var(--recess-2);border-radius:10px}
  .brief.sp .sp-sbar .sg em{grid-row:1 / 3}
  .brief.sp .sp-sbar .sg i,.brief.sp .sp-sbar .sg span{grid-column:2}
  .brief.sp .sp-sbar .s1{border-left-color:var(--criteria-bg)}.brief.sp .sp-sbar .s2{border-left-color:var(--criteria)}.brief.sp .sp-sbar .s3{border-left-color:var(--caution)}.brief.sp .sp-sbar .s4{border-left-color:var(--ink-2)}
  .brief.sp .sp-sbar .s2,.brief.sp .sp-sbar .s3,.brief.sp .sp-sbar .s4{box-shadow:var(--inner),inset 0 0 0 2px var(--caution-bg)}
}
/* Treat: one ladder. Each rung opens with what sends you there, then the move; a rail joins the rungs in order */
.brief.sp .sp-ladder{margin:10px 0 0;padding:4px 18px;border-radius:var(--r-sub);background:var(--recess);box-shadow:var(--inner)}
.brief.sp .sp-rung{position:relative;display:grid;grid-template-columns:30px minmax(0,1fr);gap:14px;padding:16px 0}
.brief.sp .sp-rung + .sp-rung{border-top:1px solid var(--hair)}
.brief.sp .sp-rung::before{content:"";position:absolute;left:14px;top:46px;bottom:-16px;width:2px;background:var(--recess-2)}
.brief.sp .sp-rung:last-child::before{display:none}
.brief.sp .sp-node{position:relative;z-index:1;display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:var(--confirm);color:var(--raised);font:800 13px/1 var(--sans)}
.brief.sp .sp-rung:last-child .sp-node{background:var(--caution)}
.brief.sp .sp-when{display:flex;flex-wrap:wrap;align-items:baseline;gap:2px 10px;margin:4px 0 6px}
.brief.sp .sp-when b{font:800 11.5px/1.3 var(--sans);letter-spacing:.08em;text-transform:uppercase;color:var(--criteria)}
.brief.sp .sp-when span{font-size:13.5px;line-height:1.4;color:var(--ink-2)}
.brief.sp .sp-when span::before{content:"when ";font-weight:700;color:var(--muted)}
.brief.sp .sp-rung:first-child .sp-when span::before{content:""}
.brief.sp .sp-stay{margin:10px 0 0;padding-top:9px;border-top:1px dashed var(--hair);font-size:14px;color:var(--ink)}
.brief.sp .sp-stay b{font-weight:650;color:var(--ink-2)}
@media (max-width:640px){.brief.sp .sp-ladder{padding:2px 14px}.brief.sp .sp-rung{grid-template-columns:26px minmax(0,1fr);gap:11px}.brief.sp .sp-node{width:26px;height:26px}.brief.sp .sp-rung::before{left:12px;top:42px}}
/* Step 1: the illness script as labelled rows in one well; the chain reads as tiers of arrow lines */
.brief.sp .sp-script{margin:14px 0 0;padding:4px 18px;border-radius:var(--r-sub);background:var(--recess);box-shadow:var(--inner)}
.brief.sp .sp-script .sr{display:grid;grid-template-columns:104px minmax(0,1fr);gap:4px 16px;padding:13px 0}
.brief.sp .sp-script .sr + .sr{border-top:1px solid var(--hair)}
